    def countGoodIntegers(self, n: int, k: int) -> int:
        def count_palindromes(length, digits):
            if length == 1:
                return sum(1 for d in digits if d % k == 0)
            if length == 2:
                return sum(1 for d in digits if d % k == 0) * 9

            half_length = (length + 1) // 2
            count = 0
            for d in digits:
                if d % k == 0:
                    remaining_digits = digits[:]
                    remaining_digits.remove(d)
