        max_area = sum(positions)

        while True:
            new_positions = positions[:]
            changed = False

            for i in range(n):
                if directions[i] == 'U':
                    if positions[i] < height:
                        new_positions[i] += 1
                        if new_positions[i] > height:
                            new_positions[i] = height - 1
                            directions = directions[:i] + 'D' + directions[i+1:]
                            changed = True
                else:  # directions[i] == 'D'
                    if positions[i] > 0:
                        new_positions[i] -= 1
                        if new_positions[i] < 0:
                            new_positions[i] = 1
                            directions = directions[:i] + 'U' + directions[i+1:]
                            changed = True

            new_area = sum(new_positions)
            if new_area > max_area:
                max_area = new_area
            else:
                break

            positions = new_positions

        return max_area

