class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        def bfs(start_x, start_y, target_x, target_y):
            queue = [(start_x, start_y, 0)]
            visited = set()
            visited.add((start_x, start_y))
            directions = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]

            while queue:
                x, y, moves = queue.pop(0)
                if x == target_x and y == target_y:
                    return moves
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny, moves + 1))
            return float('inf')

        n = len(positions)
        dp = [[0] * (1 << n) for _ in range(n)]

        for i in range(n):
            dp[i][1 << i] = bfs(kx, ky, positions[i][0], positions[i][1])

        for mask in range(1 << n):
            for i in range(n):
                if mask & (1 << i):
                    submask = mask ^ (1 << i)
                    for j in range(n):
                        if submask & (1 << j):
                            dp[i][mask] = max(dp[i][mask], dp[j][submask] + bfs(positions[i][0], positions[i][1], positions[j][0], positions[j][1]))

        result = 0
        for i in range(n):
            result = max(result, dp[i][(1 << n) - 1])

        return result

