    def validSequence(self, word1: str, word2: str) -> List[int]:
        m, n = len(word1), len(word2)
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = True

        for i in range(1, m + 1):
            for j in range(n + 1):
                if j == 0:
                    dp[i][j] = True
                elif i > 0:
                    if word1[i - 1] == word2[j - 1]:
                        dp[i][j] = dp[i - 1][j - 1]
                    else:
                        dp[i][j] = dp[i - 1][j - 1] or dp[i - 1][j]

        if not dp[m][n]:
            return []

        result = []
        i, j = m, n
        while i > 0 and j > 0:
            if word1[i - 1] == word2[j - 1]:
                result.append(i - 1)
                i -= 1
                j -= 1
            elif dp[i - 1][j - 1]:
                result.append(i - 1)
                i -= 1
                j -= 1
            else:
                i -= 1

        while j > 0:
            result.append(i - 1)
            i -= 1
            j -= 1

