class Solution:
    def remainingMethods(self, n: int, k: int, invocations: List[List[int]]) -> List[int]:
        # Create a graph to represent the invocation relationships
        graph = [[] for _ in range(n)]
        for a, b in invocations:
            graph[a].append(b)

        # Perform DFS to find all suspicious methods
        visited = [False] * n
        suspicious = set()

        def dfs(node):
            if visited[node]:
                return
            visited[node] = True
            suspicious.add(node)
            for neighbor in graph[node]:
                dfs(neighbor)

        dfs(k)

        # Check if any non-suspicious method invokes a suspicious method
        for i in range(n):
            if not visited[i]:
                for neighbor in graph[i]:
                    if neighbor in suspicious:
                        return []

        # Return all non-suspicious methods
        return [i for i in range(n) if not visited[i]]

