class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for num in nums:
            if num == 2:
                ans.append(-1)
            else:
                # Find the largest power of 2 less than num
                power_of_2 = 1
                while power_of_2 * 2 < num:
                    power_of_2 *= 2
                # The answer is the largest power of 2 less than num
                ans.append(power_of_2 - 1)
        return ans

