        MOD = 10**9 + 7

        # Calculate the number of ways to distribute n performers into x stages
        def ways_to_distribute(n, x):
            return pow(x, n, MOD)

        # Calculate the number of ways to assign scores to the bands
        def ways_to_assign_scores(bands, y):
            return sum(pow(y, b, MOD) for b in range(1, bands + 1)) % MOD

        total_ways = 0
        for bands in range(1, n + 1):
            ways = ways_to_distribute(n, x)
            ways *= ways_to_assign_scores(bands, y)
            ways %= MOD
            total_ways += ways
            total_ways %= MOD

        return total_ways

