        def is_perfect(node, depth):
            if not node:
                return True, 0
            left_is_perfect, left_depth = is_perfect(node.left, depth + 1)
            right_is_perfect, right_depth = is_perfect(node.right, depth + 1)
            if left_is_perfect and right_is_perfect and left_depth == right_depth:
                return True, left_depth + 1
            return False, 0

