class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        for i in range(n):
            if nums[i] == 1:
                continue
            min_ops = float('inf')
            for j in range(i):
                if nums[j] < nums[i]:
                    gcd = math.gcd(nums[i], nums[j])
                    if nums[j] * (nums[i] // gcd) == nums[i]:
                        min_ops = min(min_ops, dp[j] + 1)
