class Solution:
    def countOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # dp[i][j][p] means the number of ways to form an array of length i
        # with exactly j k-even conditions and the last element being p
        dp = [[[0] * (m + 1) for _ in range(k + 1)] for _ in range(n + 1)]

        # Base case: An array of length 1 can have 0 k-even conditions
        for p in range(1, m + 1):
            dp[1][0][p] = 1

        for i in range(2, n + 1):
            for j in range(k + 1):
                for p in range(1, m + 1):
                    for q in range(1, m + 1):
                        if (p * q - p - q) % 2 == 0:
                            if j > 0:
                                dp[i][j][q] = (dp[i][j][q] + dp[i - 1][j - 1][p]) % MOD
                        else:
                            dp[i][j][q] = (dp[i][j][q] + dp[i - 1][j][p]) % MOD

        # Sum up all ways to form an array of length n with exactly k k-even conditions
        result = sum(dp[n][k][p] for p in range(1, m + 1)) % MOD
        return result

