class Solution:
    def maxRemoval(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        events = []

        # Create events for the start and end of each query
        for i, (l, r) in enumerate(queries):
            events.append((l, 1, i))  # Start of query
            events.append((r + 1, -1, i))  # End of query

        # Sort events by index, then by type (start before end)
        events.sort()

        active_queries = set()
        max_active = 0
        num_decrements = [0] * n

        for idx, typ, qid in events:
            if typ == 1:
                active_queries.add(qid)
            else:
                active_queries.remove(qid)

            max_active = max(max_active, len(active_queries))

            if typ == 1:
                num_decrements[idx] += max_active

        # Check if we can make nums a zero array
        for i in range(n):
            if nums[i] > num_decrements[i]:
                return -1

        # Calculate the maximum number of removable queries
        total_queries = len(queries)
        used_queries = sum(1 for i in range(n) if nums[i] > 0)
        return total_queries - used_queries

