                        if i > 0 and j > 0:
                            dp[0][i][j] = max(dp[0][i][j], dp[0][i-1][j-1])
                        if i > 0:
                            dp[0][i][j] = max(dp[0][i][j], dp[0][i-1][j])
                        if j > 0:
                            dp[0][i][j] = max(dp[0][i][j], dp[0][i][j-1])
                        dp[0][i][j] += fruits[i][j]

                        # Child 2: (0, n-1) -> (i, j)
                        if i > 0 and j < n-1:
                            dp[1][i][j] = max(dp[1][i][j], dp[1][i-1][j+1])
                        if i > 0:
                            dp[1][i][j] = max(dp[1][i][j], dp[1][i-1][j])
                        if j < n-1:
                            dp[1][i][j] = max(dp[1][i][j], dp[1][i][j+1])
                        dp[1][i][j] += fruits[i][j]

                        # Child 3: (n-1, 0) -> (i, j)
                        if i < n-1 and j > 0:
                            dp[2][i][j] = max(dp[2][i][j], dp[2][i+1][j-1])
                        if j > 0:
                            dp[2][i][j] = max(dp[2][i][j], dp[2][i][j-1])
                        if i < n-1:
                            dp[2][i][j] = max(dp[2][i][j], dp[2][i+1][j])
                        dp[2][i][j] += fruits[i][j]

        return max(dp[0][n-1][n-1], dp[1][n-1][n-1], dp[2][n-1][n-1])

