class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # Create a max heap based on the effective value after applying operations
        max_heap = []
        for num in nums:
            # Calculate the effective value after applying both operations
            # Operation 2 is prioritized because it reduces the value more significantly
            effective_value = num - k if num >= k else num
            effective_value = effective_value / 2 if op1 > 0 else effective_value
            heapq.heappush(max_heap, (-effective_value, num))

        # Apply operations
        while op1 > 0 and max_heap:
            effective_value, num = heapq.heappop(max_heap)
            if num % 2 == 0:
                new_value = num // 2
            else:
                new_value = (num + 1) // 2
            op1 -= 1
            heapq.heappush(max_heap, (-new_value, new_value))

        while op2 > 0 and max_heap:
            effective_value, num = heapq.heappop(max_heap)
            if num >= k:
                new_value = num - k
                op2 -= 1
                heapq.heappush(max_heap, (-new_value, new_value))
            else:
                heapq.heappush(max_heap, (effective_value, num))

        # Calculate the final sum
        return sum(max(-value, 0) for _, value in max_heap)

