        for u, v in edges2:
            graph2[u].append(v)
            graph2[v].append(u)

        # Calculate distances from each node in both trees
        dist1 = [bfs(graph1, i) for i in range(n)]
        dist2 = [bfs(graph2, i) for i in range(m)]

        # Calculate the maximum number of target nodes for each node in the first tree
        result = [0] * n
        for i in range(n):
