            for j in range(m):
                if (dist1[i][j] + dist2[j][i]) % 2 == 0:
                    max_targets = max(max_targets, n + m - 1 - dist1[i][j] - dist2[j][i])
                else:
                    max_targets = max(max_targets, n + m - 1 - dist1[i][j] - dist2[j][i] + 1)
