class Solution:
    def findMinimumTime(self, strength: List[int], k: int) -> int:
        n = len(strength)
        dp = [[float('inf')] * (1 << n) for _ in range(n)]

        for mask in range(1 << n):
            for i in range(n):
                if mask & (1 << i):
                    prev_mask = mask ^ (1 << i)
                    if prev_mask == 0:
                        dp[i][mask] = strength[i]
                    else:
                        for j in range(n):
                            if prev_mask & (1 << j):
                                dp[i][mask] = min(dp[i][mask], dp[j][prev_mask] + strength[i])

