class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(num):
            if num < 2:
                return False
            for i in range(2, int(num**0.5) + 1):
                if num % i == 0:
                    return False
            return True

        if n == m:
            return 0
        if is_prime(m):
            return -1

        str_n = str(n)
        str_m = str(m)
        cost = 0

        for i in range(len(str_n)):
            if str_n[i] == str_m[i]:
                continue
            if str_n[i] < str_m[i]:
                # Increase digits
                cost += int(str_m[i]) - int(str_n[i])
                for j in range(i + 1, len(str_n)):
                    if str_n[j] != '9':
                        cost += 9 - int(str_n[j])
                        str_n = str_n[:j] + '9' + str_n[j+1:]
            else:
                # Decrease digits
                cost += int(str_n[i]) - int(str_m[i])
                for j in range(i + 1, len(str_n)):
                    if str_n[j] != '0':
                        cost += int(str_n[j])
                        str_n = str_n[:j] + '0' + str_n[j+1:]

        if int(str_n) == m and not is_prime(int(str_n)):
            return cost
        return -1

