class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        def find(x):
            while x in parent:
                while parent[x] in parent:
                    parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        parent = {}
        for num in nums:
            for multiple in range(num, threshold + 1, num):
                if multiple in nums:
                    union(num, multiple)

        return len({find(num) for num in nums})

