class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        def kadane(arr):
            max_ending_here = max_so_far = arr[0]
            for x in arr[1:]:
                max_ending_here = max(x, max_ending_here + x)
                max_so_far = max(max_so_far, max_ending_here)
            return max_so_far

        total_sum = sum(nums)
        max_subarray_sum = kadane(nums)

        if max_subarray_sum < 0:
            return max_subarray_sum

        num_count = {}
        for num in nums:
            if num in num_count:
                num_count[num] += num
            else:
                num_count[num] = num

        max_result = max_subarray_sum
        for num, value in num_count.items():
            max_result = max(max_result, total_sum - value + kadane([x for x in nums if x != num]))

        return max_result

