class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Create adjacency list with weights
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            if w > threshold:
                continue
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Check if node 0 is reachable from all other nodes
        visited = [False] * n
        queue = [0]
        while queue:
            node = queue.pop(0)
            if visited[node]:
                continue
            visited[node] = True
            for neighbor, _ in adj_list[node]:
                if not visited[neighbor]:
                    queue.append(neighbor)

        if not all(visited):
            return -1

        # Find the minimum possible value of the maximum edge weight
        max_weight = 0
        for u, v, w in edges:
            if w > threshold:
                continue
            max_weight = max(max_weight, w)

        return max_weight

