class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_subarrays = n * (n + 1) // 2

        def canMakeNonDecreasing(start, end, k):
            min_heap = []
            operations = 0

            for i in range(start, end + 1):
                if min_heap and nums[i] < min_heap[0]:
                    diff = min_heap[0] - nums[i]
                    if operations + diff > k:
                        return False
                    operations += diff
                    heapq.heapreplace(min_heap, nums[i])
                else:
                    heapq.heappush(min_heap, nums[i])

            return True

        count = 0
        for start in range(n):
            end = start
            while end < n and canMakeNonDecreasing(start, end, k):
                count += 1
                end += 1

        return total_subarrays - count

