class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7

        # Calculate the number of ways to choose k positions from m*n
        def comb(n, k):
            if k > n:
                return 0
            res = 1
            for i in range(k):
                res = res * (n - i) // (i + 1)
            return res

        # Calculate the sum of Manhattan distances for a fixed position
        def fixed_position_sum(x, y):
            above = x * (k - 1)
            below = (m - x - 1) * (k - 1)
            left = y * (k - 1)
            right = (n - y - 1) * (k - 1)
            return (above + below + left + right) % MOD

        total_sum = 0
        for i in range(m):
            for j in range(n):
                total_sum += fixed_position_sum(i, j) * comb(m * n - 1, k - 1)
                total_sum %= MOD

        return total_sum

