class Solution:
    def supersequences(self, words: List[str]) -> List[List[int]]:
        # Count the frequency of each character in all words
        total_count = Counter()
        for word in words:
            total_count += Counter(word)

        # Generate all possible SCSs
        scss = set()
        def backtrack(path, used):
            if len(path) == len(words) * 2:
                scss.add(''.join(path))
                return
            for i, word in enumerate(words):
                if not used[i]:
                    used[i] = True
                    for char in word:
                        path.append(char)
                        backtrack(path, used)
                        path.pop()
                    used[i] = False

        backtrack([], [False] * len(words))

        # Filter out permutations of each other
        unique_scss = []
        for scs in scss:
            if all(scs != perm for perm in unique_scss):
                unique_scss.append(scs)

        # Convert each SCS to its frequency array
        result = []
        for scs in unique_scss:
            freq = [0] * 26
            for char in scs:
                freq[ord(char) - ord('a')] += 1
            result.append(freq)

        return result

