class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        meetings = sorted(zip(startTime, endTime))

        # Initialize DP table
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for j in range(k + 1):
                # Option 1: Do not reschedule the current meeting
                dp[i][j] = max(dp[i][j], dp[i-1][j])

                # Option 2: Reschedule the current meeting
                if j > 0:
                    # Find the last meeting that ends before the current meeting starts
                    last_meeting = 0
                    for l in range(i-1, 0, -1):
                        if meetings[l-1][1] <= meetings[i-1][0]:
                            last_meeting = l
                            break
                    dp[i][j] = max(dp[i][j], dp[last_meeting][j-1] + meetings[i-1][0] - meetings[last_meeting-1][1])

        # The maximum free time is the maximum value in the last row of the DP table
        return max(dp[n])

