        result = [caption[0]]

        for i in range(1, n):
            if result[-1] == caption[i]:
                result.append(caption[i])
            else:
                # Try to make the current character the same as the last one
                if result[-1] < caption[i]:
                    # Move down
                    while result[-1] < caption[i] - 1:
                        result.append(chr(ord(result[-1]) + 1))
                else:
                    # Move up
                    while result[-1] > caption[i] + 1:
                        result.append(chr(ord(result[-1]) - 1))

                # Append the adjusted character
                result.append(caption[i])

        # Check if the result is a good caption
        if len(result) < 3:
            return ""

        # Ensure all groups are of at least 3 characters
        i = 0
        while i < len(result) - 2:
            if result[i] == result[i+1] == result[i+2]:
                i += 3
            else:
