    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        north = south = east = west = 0

        for move in s:
            if move == 'N':
                north += 1
            elif move == 'S':
                south += 1
            elif move == 'E':
                east += 1
            else:
                west += 1

        # Calculate the maximum possible distance without changes
        max_distance = abs(north - south) + abs(east - west)

        # We can change up to k moves to maximize the distance
        # Each change can potentially add 2 to the distance
        return max_distance + 2 * min(k, abs(north - south) + abs(east - west))

