class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        prefix_sum = [0] * (n + 1)
        suffix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + points[i]

        for i in range(n - 1, -1, -1):
            suffix_sum[i] = suffix_sum[i + 1] + points[i]

        def canAchieve(min_score):
            left_moves = m
            for i in range(n):
                if points[i] < min_score:
                    required_left = (min_score - points[i]) // 2
                    required_right = (min_score - points[i]) - required_left
                    if required_left > i or required_right > n - i - 1:
                        return False
                    left_moves -= required_left + required_right
                    if left_moves < 0:
                        return False
            return True

        low, high = 0, max(points)
        while low < high:
            mid = (low + high + 1) // 2
            if canAchieve(mid):
                low = mid
            else:
                high = mid - 1

        return low

