class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def canPlace(points, d, k):
            selected = 0
            for i in range(len(points)):
                if selected >= k:
                    break
                valid = True
                for j in range(i):
                    if selected >= k:
                        break
                    if abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]) < d:
                        valid = False
                        break
                if valid:
                    selected += 1
            return selected >= k

        points.sort()
        low, high = 0, side
        while low < high:
            mid = (low + high + 1) // 2
            if canPlace(points, mid, k):
                low = mid
            else:
                high = mid - 1
        return low

