class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        MOD = 10**9 + 7
        n = len(original)
        dp = [0] * n
        dp[0] = 1

        for i in range(1, n):
            diff = original[i] - original[i - 1]
            for j in range(bounds[i][0], bounds[i][1] + 1):
                if j - diff >= bounds[i - 1][0] and j - diff <= bounds[i - 1][1]:
                    dp[i] = (dp[i] + dp[i - 1]) % MOD

        return dp[-1]

