class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def backtrack(path, used, is_odd):
            if len(path) == n:
                return [path[:]]
            res = []
            for i in range(1, n + 1):
                if not used[i] and (is_odd != (i % 2 == 1)):
                    used[i] = True
                    path.append(i)
                    res.extend(backtrack(path, used, not is_odd))
                    path.pop()
                    used[i] = False
            return res

        used = [False] * (n + 1)
        perms = backtrack([], used, True)
        if k > len(perms):
            return []
        return perms[k - 1]

