    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        result = ['a'] * (n + m - 1)

        for i in range(n):
            if str1[i] == 'T':
                if ''.join(result[i:i+m]) != str2:
                    return ""
                result[i:i+m] = list(str2)
            else:
                if ''.join(result[i:i+m]) == str2:
                    return ""
                for j in range(m):
                    if result[i+j] < str2[j]:
                        break
                    elif result[i+j] > str2[j]:
                        result[i:i+m] = ['a'] * m
                        break
                else:
                    result[i:i+m] = [chr(ord('z') - k) for k in range(m)]

        return ''.join(result)

