class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        def count_subarrays_without_pair(pairs):
            graph = {i: set() for i in range(1, n + 1)}
            for a, b in pairs:
                graph[a].add(b)
                graph[b].add(a)

            visited = [False] * (n + 1)
            components = 0

            def dfs(node):
                stack = [node]
                while stack:
                    current = stack.pop()
                    if not visited[current]:
                        visited[current] = True
                        for neighbor in graph[current]:
                            stack.append(neighbor)

            for i in range(1, n + 1):
                if not visited[i]:
                    dfs(i)
                    components += 1

            return components

        max_subarrays = 0
        for i in range(len(conflictingPairs)):
            remaining_pairs = conflictingPairs[:i] + conflictingPairs[i+1:]
            max_subarrays = max(max_subarrays, count_subarrays_without_pair(remaining_pairs))

        total_subarrays = n * (n + 1) // 2
        return total_subarrays - max_subarrays

