class Solution:
    def applySubstitutions(self, replacements: List[List[str]], text: str) -> str:
        # Create a dictionary from the replacements list
        replacement_dict = {key: value for key, value in replacements}

        # Function to recursively replace placeholders
        def replace_placeholders(s):
            while '%' in s:
                new_s = ''
                i = 0
                while i < len(s):
                    if s[i] == '%':
                        j = i + 1
                        while j < len(s) and s[j] != '%':
                            j += 1
                        key = s[i+1:j]
                        if key in replacement_dict:
                            new_s += replacement_dict[key]
                        else:
                            new_s += s[i]
                        i = j + 1
                    else:
                        new_s += s[i]
                        i += 1
                s = new_s
            return s

        # Apply the replacement function to the text
        return replace_placeholders(text)

