class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        def common_prefix_length(s1, s2):
            min_len = min(len(s1), len(s2))
            for i in range(min_len):
                if s1[i] != s2[i]:
                    return i
            return min_len

        def longest_common_prefix_among_top_k(freq):
            if len(freq) < k:
                return 0
            top_k_words = sorted(freq.keys(), key=lambda x: freq[x], reverse=True)[:k]
            prefix_length = float('inf')
            for i in range(1, k):
                prefix_length = min(prefix_length, common_prefix_length(top_k_words[0], top_k_words[i]))
            return prefix_length

        answer = []
        word_count = Counter(words)

        for word in words:
            word_count[word] -= 1
            if word_count[word] == 0:
                del word_count[word]

            answer.append(longest_common_prefix_among_top_k(word_count))

            word_count[word] = word_count.get(word, 0) + 1

        return answer

