class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        graph = defaultdict(list)
        for u, v, length in edges:
            graph[u].append((v, length))
            graph[v].append((u, length))

        def dfs(node, parent):
            max_lengths = [0, 0]
            for neighbor, length in graph[node]:
                if neighbor != parent:
                    lengths = dfs(neighbor, node)
                    if nums[neighbor] == nums[node]:
                        lengths.sort(reverse=True)
                        max_lengths[0] = max(max_lengths[0], lengths[0])
                        if len(lengths) > 1:
                            max_lengths[1] = max(max_lengths[1], lengths[0] + lengths[1])
            return [max_lengths[0] + length, max_lengths[1]]

        total_max_length = 0
        min_nodes = float('inf')

        for i in range(len(nums)):
            lengths = dfs(i, -1)
            total_max_length = max(total_max_length, lengths[0])
            if lengths[0] > 0:
                min_nodes = min(min_nodes, lengths[0] // lengths[0] + 1)
            if lengths[1] > 0:
                min_nodes = min(min_nodes, lengths[1] // lengths[0] + 1)

        return [total_max_length, min_nodes]

