class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        index_map = {}

        # Create a map to store indices of each number in nums
        for i, num in enumerate(nums):
            if num not in index_map:
                index_map[num] = []
            index_map[num].append(i)

        def min_distance(query_index):
            num = nums[query_index]
            if num not in index_map:
                return -1

            indices = index_map[num]
            m = len(indices)
            if m == 1:
                return -1

            min_dist = float('inf')
            for i in range(m):
                dist = abs(indices[i] - query_index)
                if i > 0:
                    dist = min(dist, n - abs(indices[i] - indices[i-1]) + abs(query_index - indices[i-1]))
                if i < m - 1:
                    dist = min(dist, n - abs(indices[i] - indices[i+1]) + abs(query_index - indices[i+1]))
                min_dist = min(min_dist, dist)

            return min_dist

        return [min_distance(q) for q in queries]

