class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        n = len(t)
        max_active = 0

        # Find all blocks of '1's surrounded by '0's
        blocks = []
        i = 0
        while i < n:
            if t[i] == '0':
                start = i + 1
                while i < n and t[i] == '1':
                    i += 1
                if i < n and t[i] == '0':
                    blocks.append((start, i))
            i += 1

        # Calculate the maximum number of active sections after the trade
        for start, end in blocks:
            # Convert the block of '1's to '0's
            new_t = t[:start-1] + '0' * (end - start + 1) + t[end+1:]
            # Find the next block of '0's surrounded by '1's
            next_start = end + 1
            while next_start < n and new_t[next_start] == '0':
                next_start += 1
            if next_start < n and new_t[next_start] == '1':
                next_end = next_start + 1
                while next_end < n and new_t[next_end] == '1':
                    next_end += 1
                if next_end < n and new_t[next_end] == '0':
                    # Convert the block of '0's to '1's
                    new_t = new_t[:next_start] + '1' * (next_end - next_start) + new_t[next_end:]
                    # Count the number of active sections
                    max_active = max(max_active, new_t.count('1'))

        return max_active

