class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Check if there's any common character between s and t
        common_char = any(c in t for c in s)

        # If there's no common character, the longest palindrome is 1 (a single character)
        if not common_char:
            return 1

        # Initialize the maximum length of the palindrome
        max_length = 0

        # Check for the longest palindromic prefix in s and suffix in t
        for i in range(len(s)):
            if s[i] in t:
                # Find the longest suffix of s[:i+1] that is a prefix of t
                for j in range(len(t)):
                    if s[i::-1] == t[j:]:
                        max_length = max(max_length, 2 * (i + 1))
                        break

        # Check for the longest palindromic suffix in s and prefix in t
        for i in range(len(t)):
            if t[i] in s:
                # Find the longest prefix of t[i:] that is a suffix of s
                for j in range(len(s)):
                    if t[i:] == s[j::-1]:
                        max_length = max(max_length, 2 * (len(t) - i))
                        break

        # If no palindromic prefix/suffix combination was found, return 1
        return max_length if max_length > 0 else 1

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def find_longest_palindrome(s):
            n = len(s)
            dp = [[0] * n for _ in range(n)]
            max_length = 0

            for i in range(n-1, -1, -1):
                dp[i][i] = 1
                for j in range(i+1, n):
                    if s[i] == s[j]:
                        dp[i][j] = dp[i+1][j-1] + 2
                    else:
                        dp[i][j] = max(dp[i+1][j], dp[i][j-1])
                    max_length = max(max_length, dp[i][j])

            return max_length

        # Check if there's any common character between s and t
        common_char = any(c in t for c in s)

        # Find the longest palindromic substring in s and t
        max_s = find_longest_palindrome(s)
        max_t = find_longest_palindrome(t)

        # If there's at least one common character, we can form a palindrome by combining parts of s and t
        if common_char:
            return max(max_s, max_t, 2)
        else:
            return max(max_s, max_t)

