import heapq

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)

        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + abs(nums[i])

        min_heap = []
        for i in range(n - x + 1):
            end = i + x
            cost = prefix_sum[end] - prefix_sum[i]
            if end < n:
                cost += prefix_sum[n] - prefix_sum[end]
            heapq.heappush(min_heap, cost)

        result = float('inf')
        while k > 0:
            result = min(result, heapq.heappop(min_heap))
            k -= 1

        return result
